// Frames for "Unified List - 30 Oct 2026". Evaluated after lib.js. Everything NEW is in the first block; the rest composes as-built atoms.

// ── NEW: the five additions this round makes ──
// 1. Section head (R1 keyword as the only section head; a collapsible one takes the R2 chevron and a mono count).
const sectionHead = (t, label, count, opts) => { opts = opts || {}; return `<div style="display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: ${opts.first ? 2 : 10}px 2px 4px; min-height: 22px;"><div style="display: flex; align-items: center; gap: 8px;">${opts.collapsible ? chev(t, opts.open) : ''}${kw(t, label, opts.color)}</div><span style="font-family: ${MONO}; font-size: ${t.S.rowMono}px; color: ${t.dim}; white-space: nowrap;">${count}</span></div>`; };
// 2. Outline row: one keyword-chip row, hairline under it; pinned once the header scrolls off. The selected section takes the segmentSelected fill (ground-3).
const oChip = (t, label, count, sel, menu) => `<span style="display: inline-flex; align-items: center; gap: 6px; font-family: ${MONO}; font-size: ${t.S.outline}px; font-weight: 500; letter-spacing: 0.08em; text-transform: uppercase; color: ${sel ? t.ink : t.dim}; ${sel ? `background: ${t.g3}; ` : ''}border-radius: 4px; padding: 5px 8px; white-space: nowrap; flex: none;">${label}${count !== undefined && count !== null ? `<span style="color: ${sel ? t.ink : t.dim}; letter-spacing: 0;">${count}</span>` : ''}${menu ? `<span style="font-size: 8px; color: ${t.accT};">▾</span>` : ''}</span>`;
const outlineRow = (t, o) => { o = o || {}; const chips = []; if (o.decisions) chips.push(oChip(t, 'Decisions', o.decisions, o.sel === 'decisions', o.decisions > 1)); chips.push(oChip(t, 'Task', null, o.sel === 'task')); chips.push(oChip(t, 'Conversation', o.conversation || 0, o.sel === 'conversation')); chips.push(oChip(t, 'Timeline', null, o.sel === 'timeline')); chips.push(oChip(t, 'Runs', o.runs || 1, o.sel === 'runs', (o.runs || 1) > 1)); return `<div style="width: ${o.width || t.S.card}px; max-width: 100%; box-sizing: border-box; display: flex; gap: 4px; align-items: center; padding: 0 0 6px; margin: 0 -8px; padding-left: 8px; padding-right: 8px; width: calc(${o.width || t.S.card}px + 16px); border-bottom: 1px solid ${t.rule}; overflow: hidden; flex: none; ${o.pinned ? `background: ${t.ground}; position: relative; z-index: 2;` : ''}">${chips.join('')}</div>`; };
// 3. Page header: eyebrow (project · task · stage), serif title, one status line. Scrolls away with the page.
const pageHeader = (t, o) => `<div style="width: ${o.width || t.S.card}px; max-width: 100%; display: flex; flex-direction: column; gap: 8px; flex: none;">${kw(t, o.eyebrow)}${ask(t, o.title)}${dimText(t, o.status)}</div>`;
// 4. One-line item row: the other open items under the leading card (ask, type chip). Selecting one swaps which card leads.
const oneLineItem = (t, askText, type, cut) => `<div style="display: flex; justify-content: space-between; align-items: center; gap: 12px; border: 1px solid ${t.itemB}; border-radius: 8px; padding: 9px 14px; background: ${t.g2};"><span style="font-family: ${SERIF}; font-size: ${t.S.rowSerif}px; color: ${t.ink}; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${askText}</span>${chip(t, type, cut || 'accent')}</div>`;
// 5. Native popup for the Decisions and Runs menus (System Chrome list; drawn only to place it).
const popup = (t, items, x, y) => `<div style="position: absolute; left: ${x}px; top: ${y}px; min-width: 300px; background: ${t.g2}; border: 1px solid ${t.winB}; border-radius: 8px; padding: 5px; box-shadow: 0 10px 30px rgba(0,0,0,${t.name === 'day' ? 0.18 : 0.5}); font-family: -apple-system, 'SF Pro Text', 'Helvetica Neue', sans-serif; font-size: 13px; z-index: 5;">${items.map(i => `<div style="display: flex; align-items: center; gap: 8px; padding: 5px 10px 5px 8px; border-radius: 5px; ${i.sel ? `background: ${t.accT}; color: ${t.fillT};` : `color: ${t.ink};`}"><span style="width: 12px; flex: none; font-size: 11px;">${i.check ? '✓' : ''}</span><span style="flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${i.label}</span><span style="font-family: ${MONO}; font-size: 11px; color: ${i.sel ? t.fillT : t.dim};">${i.meta || ''}</span></div>`).join('')}</div>`;

// ── the list, both platforms ──
// Rows keyed by task (◆1): keyword = the leading open item's type, no chips by default (the open count is the ◆1 alternative),
// serif = the task's name, context = project · issue · stage · run, time = the newest open item's age. A scoped item keeps the inbox row as built.
// Needs you: one order, newest open item first (a task's position and time are its newest open item's). No urgency anywhere in the list (decided 30 Oct).
const NEEDS = [
  {key:'idem', type:'Execution failure', summary:'Idempotent decision commands', context:'freeside · #702 · Implementation · Run 3', time:'2h'},
  {key:'rig', type:'Review diminishing returns', chips:[['2 Open','accent']], summary:'Repair the acceptance rig', context:'freeside · #724 · Review · Run 2', time:'6h'},
  {key:'health', type:'System health', summary:'Backup encryption key is unreadable.', context:'studio.local · system', time:'8h', scoped:true, system:true},
  {key:'names', type:'Agent question', summary:'Bound operator task names', context:'freeside · #731 · Specification · Run 1', time:'1d'},
  {key:'codex', type:'Ready for final review', summary:'Codex credential renewal', context:'freeside · #719 · Review · Run 1', time:'1d'},
];
const WORKING = [
  {key:'time', type:'Implementing', summary:'Time grammar for inbox rows', context:'freeside · #733 · Implementation · Run 2', time:'42m'},
  {key:'summ', type:'Verifying', agent:true, summary:'Summarize review rounds on the card', context:'freeside · #654 · Verification · Run 1', time:'1h'},
  {key:'sched', type:'Parked', summary:'Scheduler occurrence drift', context:'freeside · #740 · Back at 14:00 · Claude pool exhausted', time:'3h'},
  {key:'retry', type:'Snoozed', agent:true, summary:'Retry budget for credential renewal', context:'freeside · #745 · Back at Oct 31, 9:00 AM · proposal', time:'5h'},
];
const FINISHED = [
  {key:'pool', type:'System health', typeCut:'faint', summary:'Acknowledged. Claude pool restored at 09:40.', context:'studio.local · system', time:'Oct 30, 9:41 AM', scoped:true, system:true},
  {key:'wo', type:'Published', typeCut:'faint', summary:'Write-once command identity', context:'freeside · #718 · PR #2431 · Round 2', time:'Oct 28, 4:12 PM'},
  {key:'ban', type:'Stopped', typeCut:'faint', summary:'Decision banners on the card', context:'freeside · #690 · Round 1', time:'Oct 27, 9:20 AM'},
];
const rowOf = (t, r, selected) => listRow(t, Object.assign({}, r, {selected, typeColor: r.typeCut === 'faint' ? t.faint : r.typeCut === 'accent' ? t.accT : undefined}));
const rowsCol = (t, rows, sel) => `<div style="display: flex; flex-direction: column; gap: 6px;">${rows.map(r => rowOf(t, r, r.key === sel)).join('')}</div>`;
// Mac sidebar: the tools row (the segmented control is gone), then the three sections.
const unifiedSidebar = (t, o) => { o = o || {}; const needs = o.project ? NEEDS.filter(r => !r.scoped || r.system) : NEEDS; const list = o.emptyNeeds ? [] : needs; const workOpen = !!o.workingOpen;
  const controls = `<div style="padding: 0 16px 10px; display: flex; gap: 8px; align-items: center;">${sidebarTools(t, o)}</div>`;
  const body = `<div style="padding: 0 12px 12px; display: flex; flex-direction: column; overflow: hidden; flex: 1;">${sectionHead(t, 'Needs you', list.length ? list.length : '0', {first: true})}${list.length ? rowsCol(t, list, o.sel) : emptyState(t, 'Nothing needs you.', 'Decisions you make will show up here.', 'archivebox')}${sectionHead(t, 'Working', WORKING.length, {collapsible: true, open: workOpen})}${workOpen ? rowsCol(t, WORKING, o.sel) : ''}${sectionHead(t, 'Finished', 129, {collapsible: true, open: !!o.finishedOpen})}${o.finishedOpen ? rowsCol(t, FINISHED, o.sel) : ''}</div>`;
  return sidebar(t, controls + body); };
// iPhone list: one screen, three sections, no tab bar (◆4). New Task and Devices live in the navigation bar's trailing slot.
const phoneList = (t, o) => { o = o || {}; const inner = `<div style="display: flex; flex-direction: column; gap: 0; overflow: hidden; flex: 1;">${sectionHead(t, 'Needs you', NEEDS.length, {first: true})}${rowsCol(t, NEEDS, o.sel)}${sectionHead(t, 'Working', WORKING.length, {collapsible: true, open: !!o.workingOpen})}${o.workingOpen ? rowsCol(t, WORKING) : ''}${sectionHead(t, 'Finished', 128, {collapsible: true})}</div>`;
  return phone(t, `<div style="display: flex; gap: 8px; align-items: center; flex: none;">${sidebarTools(t, o)}</div>` + inner, {navTitle: 'Freeside', navTrailing: '<span>Settings</span>', height: o.height}); };
// Project filter popup (leaves the System Chrome list: it gains a search field, so it is Freeside's). Projects are the daemon's known list, read-only.
const monogram = (t, letters, dashed) => `<span style="width: 22px; height: 22px; border-radius: 5px; flex: none; display: inline-flex; align-items: center; justify-content: center; font-family: ${MONO}; font-size: 10px; font-weight: 600; letter-spacing: 0.04em; color: ${t.dim}; ${dashed ? `border: 1px dashed ${t.ruleS}; box-sizing: border-box;` : `background: ${t.g3};`}">${letters}</span>`;
const projectPopup = (t, x, y, sel) => { const rows = [['All projects', '', 'all'], ['freeside', 'FS'], ['free-skills', 'SK'], ['straylight', 'ST'], ['scratch', 'SC'], ['No project', '', 'none']]; return `<div style="position: absolute; left: ${x}px; top: ${y}px; width: 268px; box-sizing: border-box; background: ${t.g2}; border: 1px solid ${t.winB}; border-radius: 10px; padding: 10px; box-shadow: 0 12px 34px rgba(0,0,0,${t.name === 'day' ? 0.16 : 0.5}); display: flex; flex-direction: column; gap: 8px; font-family: ${SANS}; z-index: 6;"><div style="display: flex; align-items: center; gap: 8px; border-bottom: 1px solid ${t.acc}; padding: 4px 4px 8px;">${glyphBtn(t, 'search').replace(/border: 1px solid [^;]+; background: [^;]+;/, 'width: 16px;')}<span style="font-size: ${t.S.body}px; color: ${t.faint};">Search projects…</span></div><div style="display: flex; flex-direction: column; gap: 2px;">${rows.map(r => { const on = (sel || 'all') === (r[2] || r[0]); return `<div style="display: flex; align-items: center; gap: 10px; padding: 6px 8px; border-radius: 6px; ${on ? `background: ${t.accW};` : ''}">${r[2] === 'all' ? `<span style="width: 22px; height: 22px; border-radius: 5px; background: ${t.g3}; flex: none; display: inline-flex; align-items: center; justify-content: center; color: ${t.accT}; font-size: 12px;">✓</span>` : monogram(t, r[1], r[2] === 'none')}<span style="flex: 1; font-size: ${t.S.body}px; color: ${t.ink};">${r[0]}</span></div>`; }).join('')}</div></div>`; };
// Settings sheet (R11): where Devices now lives, beside the other configuration the app will grow. Drawn only to place Devices; the view itself is a later surface.
const settingsSheet = (t) => `<div style="position: absolute; inset: 0; background: rgba(0,0,0,${t.name === 'day' ? 0.22 : 0.45}); display: flex; align-items: flex-start; justify-content: center; padding-top: 72px; z-index: 7;"><div style="width: 520px; background: ${t.g2}; border: 1px solid ${t.winB}; border-radius: 12px; overflow: hidden; display: flex; flex-direction: column; box-shadow: 0 24px 60px rgba(0,0,0,0.35);"><div style="padding: 22px 22px 18px; display: flex; flex-direction: column; gap: ${t.S.sec}px;">${head(t, 'Settings', 'This Mac and the daemon it is paired with')}${col(6, ...[['Devices', 'This Mac · iPhone · 1 revoked'], ['Notifications', 'ntfy · topic set'], ['Projects', '4 known · freeside selected'], ['Daemon', 'freesided 0.9.4 · running']].map(r => `<div style="display: flex; justify-content: space-between; align-items: center; gap: 12px; border: 1px solid ${t.itemB}; border-radius: 8px; padding: 10px 14px;"><span style="font-size: ${t.S.label}px; color: ${t.ink};">${r[0]}</span><span style="display: flex; gap: 10px; align-items: center;">${mono(t, r[1], t.S.sum, t.dim)}${link(t, '', t.S.link).replace(' ›', '›')}</span></div>`))}</div><div style="border-top: 1px solid ${t.rule}; padding: 12px 22px; display: flex; justify-content: flex-end;">${btnOut(t, 'Done', false, false)}</div></div></div>`;

// ── cards (as built; Claims, Evidence and Technical Bindings join the fold group on the Mac now that the inspector is gone) ──
const cardFolds = (t, ...xs) => folds(t, ...xs, disc(t, 'Claims', '1 agent claim'), disc(t, 'Evidence', '2 attachments · digests'), disc(t, 'Technical Bindings', 'item · task · run · digest'));
const findingCard = (t, width) => card(t, [
  head(t, 'Finding adjudication', 'Approve the proposed dispositions for these findings?'),
  dimText(t, 'Accepting applies each proposed route and the run continues to publication.'),
  item(t, `<div style="display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap;">${kw(t, 'Finding 1')}${stmt(t, 'Command handler retries without preserving the write-once command identity.')}</div>` + kwInfo(t, 'Model proposal (unverified)') + quote(t, stmt(t, 'Decline the finding', t.S.stmt, 500) + dimText(t, 'The finding assumes a retry guarantee the approved work-unit contract explicitly rejects.') + dimText(t, 'Contradicts the goal · High confidence', t.S.sum)) + disc(t, 'Reason and Alternatives'), '12px 14px'),
  item(t, `<div style="display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap;">${kw(t, 'Finding 2')}${stmt(t, 'Review-level observation: the change lacks a regression test.')}</div>` + kw(t, 'Model judgment with engine-authorized remediation (unverified)') + quote(t, stmt(t, 'Fix in this PR', t.S.stmt, 500)) + disc(t, 'Reason and Alternatives'), '12px 14px'),
  col(10, kw(t, 'Recommendation (unverified)'), `<div>The agent recommends accepting the proposed dispositions for all 2 findings, with high confidence.</div>`, actions(t, t.S.name.startsWith('mac') ? row(btnFill(t, 'Accept All Dispositions'), btnOut(t, 'Choose Another Route'), btnOut(t, 'Discuss')) : col(t.S.ctl, btnFill(t, 'Accept All Dispositions'), btnOut(t, 'Choose Another Route'), btnOut(t, 'Discuss')), more(t))),
  cardFolds(t, disc(t, 'Recorded Context'), disc(t, 'Details', 'audit digest · run · round'))
].join(''), width);
const diminCard = (t, width) => card(t, [
  head(t, 'Review diminishing returns', 'Review has reached diminishing returns. Finish now?'),
  stmt(t, 'Round 3 found no new blocking finding; the two it raised are advisory and the diff grew by 14 lines.'),
  facts(t, [fact(t, 'Cost so far', '3 rounds · 41 min'), fact(t, 'Diff growth', diff(t, 120, 8, '→ ' ) + diff(t, 134, 11))], 'Yield'),
  dimText(t, 'Continue Under Policy runs one more ordinary round that will not undo the listed fixes.'),
  actions(t, t.S.name.startsWith('mac') ? row(btnOut(t, 'Finish Now'), btnOut(t, 'Apply Then Finish'), btnOut(t, 'Discuss')) : col(t.S.ctl, btnOut(t, 'Finish Now'), btnOut(t, 'Apply Then Finish'), btnOut(t, 'Discuss')), more(t)),
  cardFolds(t, disc(t, 'Recorded Context'), disc(t, 'Details', 'audit digest · run · round'))
].join(''), width);
const blockedCard = (t, width) => card(t, [
  head(t, 'Publish blocked', 'Publication is held by a trust rule.'),
  facts(t, [fact(t, 'Rule', 'signed-commits-required'), fact(t, 'Hold', 'trust.rule_failed'), fact(t, 'Head', '4be1d0a7 on fix/acceptance-rig'), fact(t, 'Pull request', '#2440 · open')], 'Facts'),
  col(8, kwInfo(t, 'Agent summary (unverified)'), quote(t, stmt(t, 'The last commit was authored from the container without the signing key; re-signing is a one-line fix.'))),
  actions(t, row(btnFill(t, 'Rerun Trust Check'), btnOut(t, 'View PR', true), btnOut(t, 'Discuss')), more(t)),
  folds(t,
    disc(t, 'Recorded Context'),
    disc(t, 'Claims', '1 agent claim', {open: true}),
    `<div style="padding-left: 18px;">${item(t, kw(t, 'Agent claim (unverified)') + stmt(t, 'Re-signing the head commit is sufficient; no file content changes.', t.S.body) + dimText(t, 'inv-9c21 · attempt 2', t.S.sum), '10px 12px')}</div>`,
    disc(t, 'Evidence', '2 attachments · digests', {open: true}),
    `<div style="padding-left: 18px; display: flex; flex-direction: column; gap: 8px;">${fact(t, 'trust-check.log', '2.1 KB · text · 7f3a…e0b4')}${fact(t, 'commit-4be1d0a7.patch', '1.4 KB · text · 91c2…77aa')}</div>`,
    disc(t, 'Technical Bindings', 'item · task · run · digest', {open: true}),
    `<div style="padding-left: 18px; display: flex; flex-direction: column; gap: 8px;">${fact(t, 'Item', 'ai-7f3a9c21')}${fact(t, 'Task', 'tk-724-acceptance-rig')}${fact(t, 'Run', 'attempt 2 · inv-9c21')}${fact(t, 'Hold code', 'trust.rule_failed.signed_commits')}${fact(t, 'Digest', '7f3a9c21e0b4')}</div>`)
].join(''), width);
const failureCard = (t, width) => card(t, [
  head(t, 'Execution failure', 'How should this run recover?'),
  dimText(t, 'The implementation run ended in a failure the daemon could not retry on its own.'),
  facts(t, [fact(t, 'Outcome', 'Failed'), fact(t, 'Cause', 'Provider quota exhausted'), fact(t, 'Stage', 'Implementation'), fact(t, 'Invocation', 'inv-9c21 · attempt 3')], 'Failure'),
  col(8, kwInfo(t, 'Diagnostic (unverified)'), quote(t, stmt(t, 'The Claude pool returned 429 on every call after 10:02. No files were changed in this attempt.'))),
  actions(t, t.S.name.startsWith('mac') ? row(btnFill(t, 'Retry'), btnOut(t, 'Discuss')) : col(t.S.ctl, btnFill(t, 'Retry'), btnOut(t, 'Discuss')), more(t)),
  cardFolds(t, disc(t, 'Stages', '2 reached · newest Implementation'), disc(t, 'Recorded Context'))
].join(''), width);
const questionCard = (t, width) => card(t, [
  head(t, 'Agent question (unverified)', 'Which order should the migration run in?', null, true),
  dimText(t, 'Blocks the specification until answered.'),
  quote(t, `<div style="display: flex; gap: 10px; align-items: baseline;">${kw(t, 'Option 1')}${kw(t, 'Agent recommends', t.accT)}</div>` + stmt(t, 'Rename the column first, then backfill', t.S.stmt, 500) + dimText(t, 'One migration, reversible; readers see nulls for the backfill window.')),
  quote(t, kw(t, 'Option 2') + stmt(t, 'Backfill into a shadow column, then swap', t.S.stmt, 500) + dimText(t, 'Two migrations; no null window; the swap needs a maintenance pause.')),
  actions(t, col(t.S.ctl, btnFill(t, 'Answer and Retry'), btnOut(t, 'Discuss')), more(t)),
  cardFolds(t, disc(t, 'Run and Binding Details', 'Specification · blocked on operator'), disc(t, 'Recorded Context'))
].join(''), width);
const finalCard = (t, width) => card(t, [
  head(t, 'Ready for final review', 'Is this change ready for final GitHub review?'),
  col(8, kwInfo(t, 'Agent summary (unverified)'), quote(t, stmt(t, 'Renewal now re-reads the credential file on each 401 and retries once; the reviewer flagged no concerns.')), disc(t, 'Full Report', 'inv-7f3a · 2 concerns')),
  `<div style="display: flex; justify-content: space-between; gap: 12px; align-items: baseline;">${kw(t, 'Change')}${diff(t, 412, 88, '· 9 files')}</div>`,
  actions(t, col(t.S.ctl, btnFill(t, 'View PR', true), btnOut(t, 'Return to Agent')), more(t)),
  cardFolds(t, disc(t, 'Run and Binding Details', 'Head 4be1d0a7 · Base main@9c21f0e3'), disc(t, 'Recorded Context'))
].join(''), width);
const closedHealthCard = (t, width) => card(t, [
  head(t, 'System health', 'Acknowledged. Claude pool restored at 09:40.', chip(t, 'Closed', 'faint')),
  dimText(t, 'Every Claude call returned 429 from 09:02. Runs on pool A were parked until the pool answered again.'),
  facts(t, [fact(t, 'Action', 'Acknowledge · This device'), fact(t, 'Closed by', 'Daemon · pool restored'), fact(t, 'When', 'Oct 30, 9:41 AM'), fact(t, 'Parked runs', '2 · both resumed')], 'Outcome'),
  facts(t, [fact(t, 'Diagnostic', 'provider.pool_exhausted'), fact(t, 'Impairs', 'Runs on pool A'), fact(t, 'Host', 'studio.local')], 'Facts'),
  folds(t, disc(t, 'Details', 'host · code · first seen'), disc(t, 'Technical Bindings', 'item · digest'))
].join(''), width);
const healthCard = (t, width) => card(t, [
  head(t, 'System health', 'Backup encryption key is unreadable.'),
  dimText(t, 'Backups cannot be written until the key is readable. Runs continue; nothing is archived.'),
  facts(t, [fact(t, 'Diagnostic', 'backup.key_unreadable'), fact(t, 'Impairs', 'Backup'), fact(t, 'Posture', 'Degraded'), fact(t, 'Host', 'studio.local')], 'Facts'),
  actions(t, t.S.name.startsWith('mac') ? row(btnFill(t, 'Acknowledge'), btnOut(t, 'Run Doctor')) : col(t.S.ctl, btnFill(t, 'Acknowledge'), btnOut(t, 'Run Doctor')), more(t)),
  folds(t, disc(t, 'Details', 'host · code · first seen'), disc(t, 'Technical Bindings', 'item · digest'))
].join(''), width);

// ── the task body: Task disclosure, Conversation, Timeline with each run beneath (as built; the Task fold is new and houses open question 8) ──
const taskFacts = (t) => facts(t, [fact(t, 'Project', 'freeside · freeside-ai/freeside'), fact(t, 'Stage', 'Review · Round 2'), fact(t, 'Current run', 'Attempt 2 · Freeside-invoked'), fact(t, 'Agent and pool', 'claude · opus-5.5 · pool B'), fact(t, 'Isolation', 'container · standard credentials · egress: GitHub only'), fact(t, 'Branch', 'fix/acceptance-rig'), fact(t, 'Pull request', 'none yet'), fact(t, 'Policy digest', '7f3a9c21 · rein: standard')]);
const taskControls = (t) => `<div style="display: flex; gap: 8px; align-items: center; flex-wrap: wrap;">${btnWax(t, 'Stop Task', false)}${btnOut(t, 'Refresh Task Status', false, false)}<span style="color: ${t.dim}; font-weight: 500; font-size: ${t.S.body}px; padding: 0 6px;">More Actions ▾</span></div>`;
const conversation = (t, n) => col(t.S.mod, kw(t, 'Conversation'), col(8, msgAgent(t, 'Should the rig keep the legacy fixture path, or is it safe to drop it with this change?'), msgYou(t, 'Drop it; nothing outside the rig reads it.'), ...(n > 2 ? [msgAgent(t, 'Dropped. The acceptance run now passes on the bound head.')] : [])), reply(t));
const runItem = (t, o) => item(t, [
  `<div style="display: flex; justify-content: space-between; gap: 12px; align-items: center;"><div style="display: flex; gap: 8px; align-items: center;"><span style="font-family: ${SERIF}; font-weight: 500; font-size: ${t.S.stmt}px; white-space: nowrap;">${o.title}</span>${chip(t, o.chip, o.cut || 'ink')}</div>${link(t, 'Open run history')}</div>`,
  col(t.S.mod, kw(t, 'Milestones'), ...o.rail.map(r => railRow(t, r[0], r[1], r[2]))),
  disc(t, 'Run Details', o.details)
].join(''), '14px 16px', 'gap: 14px;');
